SwiftKotlin NativeDeviceMonitorApp.swift<pre><code>@main
struct NativeDeviceMonitorApp: App {
    enum Tab: Hashable { case permissions, scanner, media, api, monitor }
    @State private var tab: Tab = .permissions

    var body: some Scene {
        WindowGroup {
            TabView(selection: $tab) {
                NavigationStack { PermissionView() }
                    .tabItem { Label(AppStrings.tabPermissions, systemImage: "lock.shield") }
                    .tag(Tab.permissions)
                NavigationStack { ScannerView(onOpenPermissions: { tab = .permissions }) }
                    .tabItem { Label(AppStrings.tabScanner, systemImage: "antenna.radiowaves.left.and.right") }
                    .tag(Tab.scanner)
                // … Media · API · Monitor
            }
        }
    }
}
</code></pre> MainActivity.kt<pre><code>class MainActivity : ComponentActivity() {
    // Launchers must be registered before the Activity is STARTED,
    // so they live here and not inside a Composable.
    private val requestPermissions = registerForActivityResult(
        ActivityResultContracts.RequestMultiplePermissions(),
    ) { refreshPermissionStates() }

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        enableEdgeToEdge()
        setContent { AppTheme { AppRoot() } }   // Scaffold + NavigationBar, one `tab` state
    }
}
</code></pre> <p>Why the two entry points look different</p> <p>iOS has no Activity: services are <code>@Observable</code> singletons (<code>PermissionService.shared</code>) and every View sees the same instance. Android must register <code>ActivityResult</code> launchers in the Activity, so permission state lives there and is passed down to the screens.</p>

SwiftKotlin <pre><code>@Observable
final class BluetoothClientService {
    static let shared = BluetoothClientService()
    private(set) var devices: [BluetoothDeviceInfo] = []
    private(set) var isScanning = false
}

// In a View: just read it, SwiftUI redraws when it changes.
let ble = BluetoothClientService.shared
Text(ble.isScanning ? "Scanning…" : "Idle")
</code></pre> <pre><code>class BluetoothClientService(private val appContext: Context) {
    private val _devices = MutableStateFlow&lt;List&lt;BluetoothDeviceInfo&gt;&gt;(emptyList())
    val devices: StateFlow&lt;List&lt;BluetoothDeviceInfo&gt;&gt; = _devices.asStateFlow()

    private val _isScanning = MutableStateFlow(false)
    val isScanning: StateFlow&lt;Boolean&gt; = _isScanning.asStateFlow()
}

// In a Composable: collect it, Compose recomposes when it changes.
val scanning by ble.isScanning.collectAsState()
Text(if (scanning) "Scanning…" else "Idle")
</code></pre> <p>Same pattern: private writable, public read-only. Only the service changes its state; the UI only reads.</p>

